                door.on()  # Open the door
                print("Door opened")
            else:
                door.off() # Close the door
                print("Door closed")
        except Exception as e:
            print(f"Error controlling door: {e}")

def main():
    """Main function to run the smart bird feeder."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    picam2 = initialize_camera()
    led_pin = config.get('led_pin')
    door_pin = config.get('door_pin')

    if picam2 is None:
        print("Camera initialization failed. Exiting.")
        sys.exit(1)

    try:
        while running:
            image = capture_image(picam2)
            if image is not None:
                if detect_bird(image):
                    indicate_bird(led_pin)
                    control_feeder_door(door_pin, config)
            time.sleep(0.1)  # Reduce CPU load
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up resources
        if picam2:
            try:
                picam2.stop()
                picam2.close()
                print("Camera resources released.")
            except Exception as e:
                print(f"Error releasing camera resources: {e}")
        if led_pin:
            try:
                led = OutputDevice(led_pin)
                led.close()
                print("LED resources released.")
            except Exception as e:
                print(f"Error releasing LED resources: {e}")
        print("Program terminated.")

if __name__ == "__main__":
    main()

