import time
import signal
import sys
import random
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# --- Configuration -----------------------------------------------------------
BUZZER_PIN = 17
AMG8833_I2C_ADDR = 0x69
HUMAN_THRESHOLD_C = 30.0
POLL_INTERVAL_S = 0.1
BUZZER_DURATION_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_running = True
_buzzer = None
_i2c = None
_sensor = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def init_buzzer():
    """Initialize the buzzer on GPIO17."""
    global _buzzer
    try:
        _buzzer = Buzzer(BUZZER_PIN)
        print(f"Buzzer initialized on GPIO{BUZZER_PIN}")
    except Exception as exc:
        print(f"Error initializing buzzer: {exc}", file=sys.stderr)
        raise


def init_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    global _i2c
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
        print("I2C bus initialized")
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        raise


def init_sensor():
    """Initialize the AMG8833 thermal camera sensor."""
    global _sensor
    try:
        _sensor = adafruit_amg88xx.AMG88XX(_i2c, addr=AMG8833_I2C_ADDR)
        print("AMG8833 thermal camera initialized")
    except ValueError as exc:
        print(f"AMG8833 not found at 0x{AMG8833_I2C_ADDR:02X}: {exc}", file=sys.stderr)
        raise
    except Exception as exc:
        print(f"Error initializing AMG8833: {exc}", file=sys.stderr)
        raise


def read_thermal_data():
    """Read 8x8 thermal data from the AMG8833 or simulate it."""
    if _sensor is not None:
        try:
            return _sensor.pixels
        except Exception as exc:
            print(f"Warning: failed to read thermal data: {exc}", file=sys.stderr)
    # Simulate 8x8 thermal data with random values
    return [random.uniform(20.0, 45.0) for _ in range(64)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds HUMAN_THRESHOLD_C."""
    return any(pixel > HUMAN_THRESHOLD_C for pixel in thermal_data)


def trigger_alert(buzzer):
    """Sound the buzzer for BUZZER_DURATION_S seconds."""
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION_S)
        buzzer.off()
    except Exception as exc:
        print(f"Warning: failed to trigger buzzer: {exc}", file=sys.stderr)


def cleanup():
    """Release all resources."""
    global _buzzer, _i2c, _sensor
    if _buzzer is not None:
        try:
            _buzzer.off()
            _buzzer.close()
        except Exception:
            pass
        _buzzer = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    print("Resources released")


def main():
    """Main loop: poll thermal camera and trigger alert if human detected."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        init_buzzer()
        init_i2c()
        init_sensor()
    except Exception:
        cleanup()
        sys.exit(1)

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while _running:
            thermal_data = read_thermal_data()
            human_detected = detect_human(thermal_data)

            if human_detected:
                print("Human detected!")
                trigger_alert(_buzzer)
            else:
                print("No human detected")

            time.sleep(POLL_INTERVAL_S)

    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

