import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
LOG_FILE = 'distance_log.txt'
READ_INTERVAL = 1.0

running = True
serial_connection = None

def signal_handler(signum, frame):
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False

def initialize_serial():
    global serial_connection
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
        return True
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        return False

def read_distance():
    global serial_connection
    try:
        raw_line = serial_connection.readline()
        if not raw_line:
            return None
        line = raw_line.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): {line!r}")
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

def log_distance(timestamp, distance):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{timestamp},{distance:.2f}\n")
            f.flush()
        print(f"Logged: {timestamp},{distance:.2f}")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_serial():
        sys.exit(1)

    try:
        while running:
            distance = read_distance()
            if distance is not None:
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_distance(timestamp, distance)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

