import cv2
import numpy as np
import time
import signal
import sys
from picamera2 import Picamera2

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

cameras = []
try:
    for i in range(2):
        try:
            cam = Picamera2(camera_num=i)
            config = cam.create_preview_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                controls={"FrameDurationLimits": (33333, 33333)}
            )
            cam.configure(config)
            cam.start()
            cameras.append(cam)
        except Exception as e:
            print(f"Error initializing camera {i}: {e}", file=sys.stderr)
            cameras.append(None)

except Exception as e:
    print(f"Fatal error during camera initialization: {e}", file=sys.stderr)
    for cam in cameras:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
    cv2.destroyAllWindows()
    sys.exit(1)

try:
    while running:
        frames = []
        for i, cam in enumerate(cameras):
            if cam is None:
                continue
            try:
                frame = cam.capture_array()
                if frame is None or frame.size == 0:
                    print(f"Warning: empty frame from camera {i}", file=sys.stderr)
                    continue
                frames.append(frame)
            except Exception as e:
                print(f"Error capturing frame from camera {i}: {e}", file=sys.stderr)
                continue

        if not frames:
            time.sleep(0.01)
            continue

        combined = np.hstack(frames)
        cv2.imshow("Dual CSI Cameras", combined)

        key = cv2.waitKey(30) & 0xFF
        if key == 27:
            break

except KeyboardInterrupt:
    pass

finally:
    for cam in cameras:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
    cv2.destroyAllWindows()

