from picamera2 import Picamera2

# Configuration
LIGHTS_PIN = 17
DHT_PIN = 4
IMAGE_RESOLUTION = (640, 480)

# Global state
lights_on = False
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False

def initialize_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHTS_PIN, GPIO.OUT, initial=GPIO.LOW)
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"GPIO initialization failed: {e}. Falling back to simulated GPIO mode.")
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHTS_PIN, GPIO.OUT, initial=GPIO.LOW)

def initialize_dht11():
    try:
        dht_device = adafruit_dht.DHT11(board.D4)
        print("DHT11 sensor initialized successfully.")
        return dht_device
    except Exception as e:
        print(f"DHT11 sensor initialization failed: {e}. Falling back to simulated temperature.")
        return None

def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_still_configuration(main={"size": IMAGE_RESOLUTION})
        picam2.configure(config)
        picam2.start()
        print("Camera initialized successfully.")
