            raise RuntimeError("Sensor returned None")
        return temperature
    except RuntimeError as e:
        print(f"DHT11 read error: {e}. Falling back to simulated temperature.")
        return 25.0
    except Exception as e:
        print(f"Unexpected error reading temperature: {e}. Falling back to simulated temperature.")
        return 25.0

def capture_image(picam2):
    if picam2 is None:
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        image_path = f"greenhouse_{timestamp}.jpg"
        picam2.capture_file(image_path)
        print(f"Image captured: {image_path}")
        return image_path
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def listen_for_command():
