import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("picamera_ws")


class WebSocketHandler:
    """Thread-safe WebSocket client handler for broadcasting camera frames."""

    def __init__(self):
        self.connections: int = 0
        self.lock = threading.Lock()
        self._shutdown = threading.Event()

    def has_connections(self) -> bool:
        """Return True if any client is connected."""
        with self.lock:
            return self.connections > 0

    def broadcast(self, data: bytes) -> None:
        """Broadcast data to all connected clients. Runs in a thread-safe loop."""
        if self._shutdown.is_set():
            return
        with self.lock:
            if self.connections == 0:
                return
            try:
                for conn in self._connections:
                    conn.write(data)
                    conn.flush()
            except Exception as exc:
                logger.error("Broadcast error: %s", exc)

    def add_connection(self, conn) -> None:
        """Add a new WebSocket connection."""
        with self.lock:
            self.connections += 1
            self._connections.add(conn)

    def remove_connection(self, conn) -> None:
        """Remove a WebSocket connection."""
        with self.lock:
            self.connections -= 1
            self._connections.discard(conn)

    def shutdown(self) -> None:
        """Signal all connected clients to stop."""
        self._shutdown.set()


class CameraStream:
    """Thread-safe camera stream for motion detection and broadcasting."""

    def __init__(self, width: int = 640, height: int = 480, fps: int = 10):
        self.width = width
        self.height = height
        self.fps = fps
        self.buffer = io.BytesIO()
        self.frame_lock = threading.Lock()
        self.prev_frame: Optional[np.ndarray] = None
        self.detect_motion_function: Optional[Callable[[np.ndarray, np.ndarray], None]] = None
        self.picam2: Optional[Picamera2] = None
        self._shutdown = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def configure(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]) -> None:
        """Configure the motion detection callback."""
        if not callable(detect_motion_function):
            raise ValueError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function

    def start(self) -> None:
        """Start the camera stream in a background thread."""
        if self._thread is not None and self._thread.is_alive():
            logger.warning("Camera already started")
            return
        self._shutdown.clear()
        self.picam2 = Picamera2()
        config = self.picam2.create_video_configuration(
            main={"size": (self.width, self.height), "format": "RGB888"},
            lores={"size": (self.width, self.height), "format": "YUV420"},
        )
        self.picam2.configure(config)
        self.picam2.start()
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()
        logger.info("Camera started: %dx%d @ %d fps", self.width, self.height, self.fps)

    def _run(self) -> None:
        """Main capture loop."""
        try:
            while not self._shutdown.is_set():
                frame = self.picam2.capture_array("lores")
                if frame is None:
                    logger.warning("capture_array returned None")
                    time.sleep(0.05)
                    continue
                with self.frame_lock:
                    self.prev_frame = frame.copy()
                if self.detect_motion_function is not None:
                    self.detect_motion_function(self.prev_frame, frame)
        except Exception as exc:
            logger.error("Camera loop error: %s", exc)
        finally:
            self.stop()

    def stop(self) -> None:
        """Stop the camera stream and release resources."""
        if self._thread is not None and self._thread.is_alive():
            self._shutdown.set()
            self._thread.join(timeout=2.0)
            if self._thread.is_alive():
                logger.warning("Camera thread did not stop within timeout")
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception as exc:
                logger.error("Error stopping camera: %s", exc)
            finally:
                self.picam2 = None
        logger.info("Camera stopped")

    def get_frame(self) -> Optional[np.ndarray]:
        """Return the latest processed frame, or None if unavailable."""
        with self.frame_lock:
            return self.prev_frame.copy() if self.prev_frame is not None else None

    def get_jpeg_frame(self) -> Optional[bytes]:
        """Capture a JPEG frame and return JPEG bytes, or None on error."""
        try:
            frame = self.picam2.capture_array("lores")
            if frame is None:
                logger.warning("capture_array returned None")
                return None
            ok, encoded = cv2.imencode(".jpg", frame)
            if not ok:
                logger.warning("JPEG encoding failed")
                return None
            return encoded.tobytes()
        except Exception as exc:
            logger.error("JPEG capture error: %s", exc)
            return None


def _signal_handler(signum, frame, stream: CameraStream):
    """Handle SIGINT/SIGTERM by stopping the camera."""
    logger.info("Signal %d received, shutting down camera", signum)
    stream.stop()


def main() -> None:
    """Example usage: broadcast camera frames to WebSocket clients."""
    stream = CameraStream(width=640, height=480, fps=10)
    handler = WebSocketHandler()

    def detect_motion(prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
        """Motion detection callback: log frame boundaries."""
        if prev_frame is None or curr_frame is None:
            return
        try:
            if prev_frame.shape != curr_frame.shape:
                logger.info("Frame shape mismatch: prev=%s curr=%s", prev_frame.shape, curr_frame.shape)
                return
            if np.any(prev_frame != curr_frame):
                logger.info("Motion detected at frame boundary")
        except Exception as exc:
            logger.error("Motion detection error: %s", exc)

    stream.configure(detect_motion)

    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, stream))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, stream))

    stream.start()

    try:
        while True:
            frame = stream.get_frame()
            if frame is not None:
                logger.info("Frame available: %s", frame.shape)
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        stream.stop()


if __name__ == "__main__":
    main()

