import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Accumulates MJPEG frames from a picamera2 stream and flushes them to an output sink.
    """

    def __init__(self, c: Picamera2):
        self.c = c
        self.b = io.BytesIO()
        self.frame_type = 0  # 0 = unknown, 1 = I-frame, 2 = P-frame, 3 = B-frame

    def write(self, d: bytes) -> int:
        """
        Called by picamera2's MJPEG callback.
        Accumulates bytes until a complete frame is complete (frame_type != 1) or the stream ends.
        """
        try:
            self.b.write(d)
            if d.endswith(b'\xff\xd9'):
                # Complete frame detected
                if self.frame_type != 1:
                    self.flush()
                self.frame_type = 0
            elif d.startswith(b'\xff\xd8'):
                # New SOI marker
                self.frame_type = 0
            return len(d)
        except (io.IOError, OSError) as e:
            logger.error(f"Error writing to CameraStreamBuffer: {e}")
            return 0

    def flush(self):
        """
        Flush the accumulated buffer to the output sink.
        """
        try:
            if self.b.tell() > 0:
                self.c.output.write(self.b.getvalue())
                self.b.seek(0)
                self.b.truncate()
        except (io.IOError, OSError) as e:
            logger.error(f"Error flushing CameraStreamBuffer: {e}")


