                self.frame_type = 0
            elif d.startswith(b'\xff\xd8'):
                # New SOI marker
                self.frame_type = 0
                if self.previous_frame is not None:
                    self.detect_motion()
                self.previous_frame = None
            return len(d)
        except (io.IOError, OSError) as e:
            logger.error(f"Error writing to MotionDetectionBuffer: {e}")
            return 0

    def flush(self):
        """
        Flush the accumulated buffer to the output sink.
        """
        try:
            if self.b.tell() > 0:
                self.f(self.previous_frame, cv2.imdecode(np.frombuffer(self.b.getvalue(), cv2.IMREAD_COLOR)))
                self.b.seek(0)
                self.b.truncate()
        except (cv2.error, ValueError, TypeError) as e:
            logger.error(f"Error decoding frame in MotionDetectionBuffer: {e}")
        except (io.IOError, OSError) as e:
            logger.error(f"Error flushing MotionDetectionBuffer: {e}")

    def detect_motion(self):
        """
        Decode the previously accumulated JPEG frame and pass it to the motion callback.
        """
        try:
            if self.b.tell() > 0:
                frame = cv2.imdecode(np.frombuffer(self.b.getvalue(), cv2.IMREAD_COLOR))
                if frame is not None:
                    self.f(self.previous_frame, frame)
                self.previous_frame = frame
        except (cv2.error, ValueError, TypeError) as e:
            logger.error(f"Error decoding frame in detect_motion: {e}")
        except (io.IOError, OSError) as e:
            logger.error(f"Error flushing MotionDetectionBuffer: {e}")

