import signal
import sys
import time
import logging
import pygame.mixer
import cv2
from picamera2 import Picamera2
from gpiozero import Button, DoorLock
from config import Config

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class DoorController:
    def __init__(self, config):
        self.config = config
        self.running = True
        self.face_recognizer = None
        self.picam2 = None
        self.door = None
        self.button = None
        self.mixer = None
        self.welcome_sound = None
        self.wait_sound = None
        self.later_sound = None

    def initialize_hardware(self):
        try:
            self.door = DoorLock(18)
            self.button = Button(17, pull_up=True)
            logger.info("GPIO initialized: door=GPIO18, button=GPIO17")
        except Exception as e:
            logger.error(f"Failed to initialize GPIO: {e}")
            raise

        try:
            self.mixer = pygame.mixer.init(48000)
            self.welcome_sound = pygame.mixer.Sound(self.config.WELCOME_SOUND_FILE)
            self.wait_sound = pygame.mixer.Sound(self.config.WAIT_SOUND_FILE)
            self.later_sound = pygame.mixer.Sound(self.config.LATER_SOUND_FILE)
            logger.info("Sound files loaded")
        except Exception as e:
            logger.error(f"Failed to load sound files: {e}")
            self.cleanup()
            raise

    def initialize_face_recognizer(self):
        try:
            self.face_recognizer = cv2.face.EigenFaceRecognizer_create()
            self.face_recognizer.read(self.config.TRAINING_FILE)
            logger.info("Face recognizer loaded")
        except Exception as e:
            logger.error(f"Failed to load face recognizer: {e}")
            raise

    def initialize_camera(self):
        try:
            self.picam2 = Picamera2()
            self.picam2.configure(self.picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
            self.picam2.start()
            logger.info("Camera initialized")
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            raise

    def recognize_face(self, image):
        try:
            gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            face_coordinates = self.face_recognizer.detectMultiScale(gray_image, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
            if len(face_coordinates) == 1:
                x, y, w, h = face_coordinates[0]
                cropped_face = gray_image[y:y+h, x:x+w]
                label, confidence = self.face_recognizer.predict(cropped_face)
                return label, confidence
            return None, None
        except Exception as e:
            logger.error(f"Face recognition error: {e}")
            return None, None

    def play_sound(self, sound):
        try:
            sound.play()
        except Exception as e:
            logger.error(f"Failed to play sound: {e}")

    def unlock_door(self):
        try:
            self.door.open()
            logger.info("Door unlocked")
        except Exception as e:
            logger.error(f"Failed to unlock door: {e}")

    def lock_door(self):
        try:
            self.door.close()
            logger.info("Door locked")
        except Exception as e:
            logger.error(f"Failed to lock door: {e}")

    def cleanup(self):
        logger.info("Cleaning up resources...")
        if self.picam2:
            try:
                self.picam2.stop()
            except Exception:
                pass
        if self.mixer:
            try:
                pygame.mixer.quit()
            except Exception:
                pass
        if self.door:
            try:
                self.door.close()
            except Exception:
                pass
        if self.button:
            try:
                self.button.close()
            except Exception:
                pass
        logger.info("Cleanup complete")

    def signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        self.running = False

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        try:
            self.initialize_hardware()
            self.initialize_face_recognizer()
            self.initialize_camera()

            while self.running:
                if self.button.is_button_up():
                    logger.info("Button pressed")
                    image = self.picam2.capture_array()
                    label, confidence = self.recognize_face(image)

                    if label == self.config.POSITIVE_LABEL and confidence < self.config.POSITIVE_THRESHOLD:
                        self.unlock_door()
                        self.play_sound(self.welcome_sound)
                    else:
                        self.play_sound(self.wait_sound)
                else:
                    time.sleep(0.1)

        except Exception as e:
            logger.error(f"Fatal error: {e}")
        finally:
            self.cleanup()

if __name__ == "__main__":
    controller = DoorController(Config())
    controller.run()

