        cleanup()
        return None

    try:
        sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
        return sensor
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        cleanup()
        return None

def init_light_sensor():
    """Initialize the TSL2561 luminosity sensor."""
    global display, i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

    while not i2c_bus.try_lock():
        time.sleep(0.01)

    try:
        devices = i2c_bus.scan()
    finally:
        i2c_bus.unlock()

    if 0x39 not in devices:
        print("TSL2561 not found at address 0x39. Check wiring.")
        cleanup()
        return None

    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=0x39)
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        cleanup()
        return None

def read_sensor_data(sensor):
    """Read temperature, humidity, pressure, and light intensity from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        light = sensor.lux
        return temperature, humidity, pressure, light
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None, None

def update_display(display, temperature, humidity, pressure, light):
    """Update the OLED display with sensor readings."""
    try:
        display.fill(0)
        display.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
        display.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
        display.text(f"Pressure: {pressure:.1f} hPa", 0, 32, 1)
        display.text(f"Light: {light:.1f} lux", 0, 48, 1)
        display.show()
    except Exception as e:
        print(f"Error updating display: {e}")

def main():
    """Main loop: initialize sensors, read data, and update display."""
    global running

    signal.signal(signal.SIGINT, signal_handler)

    display = init_display()
    if display is None:
