    sensor = init_sensor()
    if sensor is None:
        sys.exit(1)

    light_sensor = init_light_sensor()
    if light_sensor is None:
        sys.exit(1)

    try:
        while running:
            temperature, humidity, pressure, light = read_sensor_data(sensor)
            if temperature is not None and humidity is not None and pressure is not None and light is not None:
                update_display(display, temperature, humidity, pressure, light)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

