        return None

def initialize_lcd(i2c_bus):
    """Initialize the 16x2 I2C LCD display."""
    try:
        lcd = character_lcd.Character_LCD_I2C(i2c_bus, LCD_I2C_ADDRESS)
        lcd.clear()
        return lcd
    except Exception as e:
        print(f"Error initializing LCD at address 0x{LCD_I2C_ADDRESS:02X}: {e}")
        return None

def initialize_dht22(pin):
    """Initialize the DHT22 sensor."""
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        return dht_device
    except Exception as e:
