        return None

def read_dht22_data(dht_device):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None values")
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 often has transient read errors; retry once
        print(f"DHT22 read error (transient): {e}")
        time.sleep(0.1)
        return dht_device.temperature, dht_device.humidity
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None

def update_lcd(lcd, temperature, humidity):
    """Update the LCD display with temperature and humidity."""
    try:
        lcd.clear()
        lcd.message = f"Temp: {temperature:.1f} C"
        lcd.message2 = f"Humidity: {humidity:.1f}%"
    except Exception as e:
        print(f"Error updating LCD: {e}")

def cleanup():
    """Clear the LCD display and release resources."""
    global lcd, dht_device
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass

def main():
    """Main function to read sensor data and update the LCD."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C bus. Exiting.")
        sys.exit(1)

    lcd = initialize_lcd(i2c_bus)
    if lcd is None:
        print("Failed to initialize LCD. Exiting.")
        cleanup()
        sys.exit(1)

    dht_device = initialize_dht22(DHT_PIN)
    if dht_device is None:
        print("Failed to initialize DHT22. Exiting.")
        cleanup()
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22_data(dht_device)
            if temperature is not None and humidity is not None:
                update_lcd(lcd, temperature, humidity)
            else:
                print("Failed to read sensor data. Retrying...")

            # Sleep in small increments to allow prompt signal handling
            slept = 0
            while slept < UPDATE_INTERVAL and running:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    main()

