import json
import random
import time
import signal
import sys
import threading

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
PUBLISH_COUNT = 5
PUBLISH_INTERVAL = 1.0
MAX_RETRIES = 3
RETRY_DELAY = 2.0

shutdown_event = threading.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    """Callback for MQTT v2 CONNACK (reason_code == 0)."""
    if reason_code == 0:
        print("Connected to broker")
        shutdown_event.set()
    else:
        print(f"Connection failed with reason code {reason_code}")
        shutdown_event.set()


def on_publish(client, userdata, mid, reason_code, properties):
    """Callback for MQTT v2 PUBLISH acknowledgement."""
    if reason_code != 0:
        print(f"Publish failed for message ID {mid} with reason code {reason_code}")
    else:
        print(f"Message {mid} published successfully")


def build_payload(index):
    """Build a JSON payload for a simulated temperature reading."""
    temperature = round(random.uniform(19.0, 26.0), 2)
    return json.dumps({"index": index, "temperature": temperature})


def publish_message(client, topic, payload, mid):
    """Publish a single message with retry logic."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            info = client.publish(topic, payload, qos=1, mid=mid)
            if info.rc == mqtt.MQTT_ERR_SUCCESS:
                return True
            print(f"Publish attempt {attempt}/{MAX_RETRIES} failed with rc={info.rc}")
        except Exception as e:
            print(f"Publish attempt {attempt}/{MAX_RETRIES} failed: {e}")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    print(f"Failed to publish message after {MAX_RETRIES} attempts")
    return False


def main():
    """Main entry point: connect, publish, wait for shutdown."""
    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-classroom-publisher",
    )
    client.on_connect = on_connect
    client.on_publish = on_publish

    # Register signal handlers for clean shutdown
    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        shutdown_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    connected = False
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            client.connect(BROKER, PORT, KEEPALIVE)
            client.loop_start()
            connected = True
            break
        except Exception as e:
            print(f"Connection attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)

    if not connected:
        print("Failed to connect to broker after all retries")
        sys.exit(1)

    message_ids = []
    try:
        for i in range(PUBLISH_COUNT):
            if shutdown_event.is_set():
                print("Shutdown requested, stopping publish loop")
                break

            payload = build_payload(i)
            mid = client.publish(TOPIC, payload, qos=1)
            message_ids.append(mid.mid)
            print(f"Published message {i+1}/{PUBLISH_COUNT}: {payload}")

            # Wait for CONNACK or publish callback
            shutdown_event.wait(timeout=PUBLISH_INTERVAL)
            if shutdown_event.is_set():
                break

            if not shutdown_event.wait(timeout=PUBLISH_INTERVAL):
                print(f"Timeout waiting for publish callback for message {i+1}")
                break

        if shutdown_event.is_set():
            print("Shutdown requested, stopping publish loop")
        else:
            print(f"Published {PUBLISH_COUNT} messages successfully")

    except Exception as e:
        print(f"Unexpected error during publish: {e}")
    finally:
        # Clean disconnect on all exit paths
        try:
            client.loop_stop()
            client.disconnect()
            print("Disconnected from broker")
        except Exception as e:
            print(f"Error during disconnect: {e}")

        if shutdown_event.is_set():
            sys.exit(0)

        # Wait for all callbacks to complete
        for mid in message_ids:
            shutdown_event.wait(timeout=PUBLISH_INTERVAL)
            if shutdown_event.is_set():
                break

        if shutdown_event.is_set():
            print("Shutdown requested, stopping publish loop")
        else:
            print(f"All {PUBLISH_COUNT} messages acknowledged")


if __name__ == "__main__":
    main()

