import serial
import signal
import sys
import time
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_weather_data(data):
    parts = data.split(',')
    if len(parts) != 3:
        return None, None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
        pressure = float(parts[2])
    except ValueError:
        return None, None, None
    if not (-40.0 <= temperature <= 85.0):
        return None, None, None
    if not (0.0 <= humidity <= 100.0):
        return None, None, None
    if not (800.0 <= pressure <= 1200.0):
        return None, None, None
    return temperature, humidity, pressure

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            if not raw:
                continue
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue
            temperature, humidity, pressure = parse_weather_data(line)
            if temperature is not None and humidity is not None and pressure is not None:
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                print(f"[{timestamp}] Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, Pressure: {pressure:.1f} hPa")
            else:
                print(f"Warning: Invalid data format received: {line!r}")
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

