import signal
import sys
import time

from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 100
TEMP_THRESHOLD = 40.0
FAN_ON_DUTY = 100.0
FAN_OFF_DUTY = 20.0
READ_INTERVAL = 5.0

fan = None
running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None


def main():
    global fan

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print(f"Threshold: {TEMP_THRESHOLD}°C, fan ON: {FAN_ON_DUTY}%, fan OFF: {FAN_OFF_DUTY}%")

    try:
        while running:
            temp = read_cpu_temp()

            if temp is not None:
                if temp > TEMP_THRESHOLD:
                    fan.value = FAN_ON_DUTY / 100.0
                    print(f"Temperature {temp:.1f}°C > {TEMP_THRESHOLD}°C -> fan ON ({FAN_ON_DUTY}%)")
                else:
                    fan.value = FAN_OFF_DUTY / 100.0
                    print(f"Temperature {temp:.1f}°C <= {TEMP_THRESHOLD}°C -> fan OFF ({FAN_OFF_DUTY}%)")
            else:
                print("Skipping this cycle due to temperature read failure.")

            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if fan is not None:
            try:
                fan.value = 0.0
                fan.close()
            except Exception:
                pass
        print("Fan control stopped and GPIO resources released.")


if __name__ == "__main__":
    main()

