#!/usr/bin/env python3
"""
LED Control Program for Raspberry Pi

Controls a physical LED on GPIO17 (BCM) based on user input.
Uses RPi.GPIO with robust error handling and clean resource release.
"""

import RPi.GPIO as GPIO
import time
import sys

# GPIO pin for the LED (BCM numbering)
LED_PIN = 17

def setup_gpio():
    """Initialise GPIO mode and set up the LED pin as an output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        print("GPIO setup complete.")
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def cleanup_gpio():
    """Safely release the GPIO pin and clean up."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
        print("GPIO cleanup complete.")
    except Exception as e:
        print(f"GPIO cleanup error: {e}", file=sys.stderr)

def main():
    """Main function to control the LED based on user input."""
    setup_gpio()
    led_state = False
    try:
        while True:
            try:
                user_input = input("Turn LED on (y/n)? ").strip().lower()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == "y":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
                print(f"LED is {'ON' if led_state else 'OFF'}")
            elif user_input == "n":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
                print(f"LED is {'ON' if led_state else 'OFF'}")
            else:
                print("Invalid input")

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

