import RPi.GPIO as GPIO
import time
import threading
import signal
import sys

# Constants
DEFAULT_LOG_FILE = "server.log"
RECEIVE_INTERVAL = 0.1

# Global variables
server_running = False
receive_thread = None
log_file = DEFAULT_LOG_FILE

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
except Exception as e:
    print(f"Error initializing GPIO: {e}")
    sys.exit(1)

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global server_running, receive_thread
    print("\nShutting down server...")
    server_running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    GPIO.cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to handle commands
def handle_command(command):
    global server_running, receive_thread, log_file

    if not server_running:
        print("Server not running. Start the server first.")
        return

    parts = command.split()
    if not parts:
        return

    command = parts[0].lower()

    if command == "start":
        if len(parts) < 2:
            print("Usage: start <filename>")
            return
        filename = parts[1]
        try:
            with open(filename, "w") as f:
                f.write("")
            log_file = filename
            print(f"Server started. Logging to {filename}")
            server_running = True
            receive_thread = threading.Thread(target=receive_data, daemon=True)
            receive_thread.start()
        except IOError as e:
            print(f"Error starting server: {e}")

    elif command == "stop":
        server_running = False
        if receive_thread and receive_thread.is_alive():
            receive_thread.join(timeout=2.0)
        print("Server stopped.")

    elif command == "help":
        if len(parts) == 1:
            print("Available commands:")
            print("start <filename> - Start the server and log to a file")
            print("stop - Stop the server")
            print("help [command] - Display help for a specific command")
            print("display - Display the contents of the log file")
            print("send <data> - Send data using DOG.send()")
            print("write <data> - Write data directly to the log file")
            print("exit - Exit the server")
        else:
            help_commands = {
                "start": "Start the server and log to a file",
                "stop": "Stop the server",
                "help": "Display help for a specific command",
                "display": "Display the contents of the log file",
                "send": "Send data using DOG.send()",
                "write": "Write data directly to the log file",
                "exit": "Exit the server"
            }
            if parts[1] in help_commands:
                print(help_commands[parts[1]])
            else:
                print("Invalid help command. Use 'help' to view available commands.")

    elif command == "display":
        try:
            with open(log_file, "r") as f:
                print(f.read())
        except IOError as e:
            print(f"Error displaying log file: {e}")

    elif command == "send":
        if len(parts) < 2:
            print("Usage: send <data>")
            return
        data = " ".join(parts[1:])
        try:
            with open(log_file, "a") as f:
                f.write(data + "\n")
            print(f"Sent: {data}")
        except IOError as e:
            print(f"Error sending data: {e}")

    elif command == "write":
        if len(parts) < 2:
            print("Usage: write <data>")
            return
        data = " ".join(parts[1:])
        try:
            with open(log_file, "a") as f:
                f.write(data + "\n")
            print(f"Wrote: {data}")
        except IOError as e:
            print(f"Error writing to log file: {e}")

    elif command == "exit":
        server_running = False
        if receive_thread and receive_thread.is_alive():
            receive_thread.join(timeout=2.0)
        GPIO.cleanup()
        sys.exit(0)

    else:
        print("Invalid command. Use 'help' to view available commands.")

# Function to receive data from DOG
def receive_data():
    global server_running
    while server_running:
        try:
            data = DOG.receive()
            if data:
                try:
                    with open(log_file, "a") as f:
                        f.write(data + "\n")
                except IOError as e:
                    print(f"Error writing to log file: {e}")
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(RECEIVE_INTERVAL)

# Main function
if __name__ == "__main__":
    try:
        import DOG
        print("Server started. Press Ctrl+C to exit.")
        while True:
            try:
                command = input("Enter command: ").strip()
                handle_command(command)
            except EOFError:
                print("\nEOF received. Exiting...")
                break
    except ImportError:
        print("Error: DOG library not found. Please install it.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()

