import RPi.GPIO as GPIO
import time
import requests
import sys

# Configuration
GPIO_PIN = 17
SERVER_URL = "http://example.com/alert"
CHECK_INTERVAL = 1  # seconds
REQUEST_TIMEOUT = 5  # seconds

def setup_gpio():
    """Initialize GPIO with BCM numbering and pull-up resistor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def send_alert():
    """Send an HTTP POST request to the server with a timeout."""
    try:
        response = requests.post(SERVER_URL, json={"alert": "Power failure detected"}, timeout=REQUEST_TIMEOUT)
        response.raise_for_status()
        print("Alert sent successfully.")
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}", file=sys.stderr)

def main():
    setup_gpio()
    print("Monitoring GPIO pin 17 for voltage status. Press Ctrl+C to exit.")

    try:
        while True:
            try:
                power_present = GPIO.input(GPIO_PIN)
            except Exception as e:
                print(f"Error reading GPIO pin: {e}", file=sys.stderr)
                time.sleep(CHECK_INTERVAL)
                continue

            if power_present == GPIO.HIGH:
                print("Power is present (HIGH).")
            else:
                print("Power failure detected (LOW).")
                send_alert()

            time.sleep(CHECK_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
