import time
import board
import busio
import adafruit_fingerprint

# Constants
FINGERPRINT_SENSOR_ADDRESS = 0x26
I2C_RETRY_DELAY = 1  # seconds

def initialize_i2c():
    """Initialize the I2C bus using board.SCL and board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C bus: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing I2C bus: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the fingerprint sensor at the specified address."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, address=FINGERPRINT_SENSOR_ADDRESS)
        return fingerprint_sensor
    except ValueError as e:
        print(f"Error initializing fingerprint sensor at address 0x{FINGERPRINT_SENSOR_ADDRESS:02X}: {e}")
        return None
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor at address 0x{FINGERPRINT_SENSOR_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None

def authenticate_user(fingerprint_sensor):
    """
    Authenticate the user by capturing a fingerprint image and searching the database.
    Returns True if the user is authenticated, False otherwise.
    """
    try:
        print("Place your finger on the sensor...")
        if not fingerprint_sensor.get_image():
            print("No finger detected.")
            return False

        print("Image acquired. Processing...")
        if not fingerprint_sensor.image_2_tz(1):
            print("Image conversion failed.")
            return False

        print("Searching database...")
        if not fingerprint_sensor.finger_search():
            print("No match found.")
            return False

        print("Access Granted")
        return True

    except RuntimeError as e:
        print(f"Error during fingerprint authentication: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error during fingerprint authentication: {e}")
        return False

def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            if authenticate_user(fingerprint_sensor):
                time.sleep(1)  # Add a delay to prevent rapid re-authentication
            else:
                time.sleep(1)  # Add a delay to prevent rapid denials
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized. Exiting.")

if __name__ == "__main__":
    main()

