"""
Grid-based path planning for a manufacturing quality-control robot.
Uses breadth-first search to plan a route from inspection start to defect.
Drives a GPIO status LED on GPIO18 (BCM) with 330 ohm resistor to ground.
"""

import sys
import time
import logging
from collections import deque

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
LED_PIN = 18
GRID_SIZE = 5
START_CELL = (0, 0)
DEFECT_CELL = (4, 4)
SUCCESS_LED_ON_TIME = 2.0
FAILURE_LED_ON_TIME = 0.5
FAILURE_LED_BLINK_COUNT = 3
FAILURE_LED_BLINK_INTERVAL = FAILURE_LED_ON_TIME / FAILURE_LED_BLINK_COUNT

# Global flag for graceful shutdown
running = True


def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    logger.info("Shutdown signal received. Cleaning up...")
    running = False


def validate_grid_dimensions(grid_size):
    """Validate that grid size is a positive integer."""
    if not isinstance(grid_size, int) or grid_size <= 0:
        raise ValueError(f"Grid size must be a positive integer, got {grid_size}")


def create_grid(grid_size):
    """Create a 2D occupancy grid with 1 indicating obstacle and 0 indicating free space."""
    try:
        grid = [[1] * grid_size for _ in range(grid_size)]
        return grid
    except Exception as e:
        logger.error(f"Failed to create grid: {e}")
        raise


def is_valid_cell(cell, grid_size):
    """Check if a cell is within the grid bounds."""
    if not isinstance(cell, tuple) or len(cell) != 2:
        return False
    x, y = cell
    return 0 <= x < grid_size and 0 <= y < grid_size


def get_neighbors(cell, grid_size):
    """Return list of valid neighbors for a given cell."""
    x, y = cell
    neighbors = [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
    return [n for n in neighbors if is_valid_cell(n, grid_size)]


def plan_route(grid, start_cell, defect_cell):
    """Plan a route using breadth-first search. Returns path length or None on failure."""
    if not is_valid_cell(start_cell, GRID_SIZE) or not is_valid_cell(defect_cell, GRID_SIZE):
        logger.error(f"Invalid start or defect cell: {start_cell}, {defect_cell}")
        return None

    if grid[start_cell[0]][start_cell[1]] == 1:
        logger.error(f"Start cell {start_cell} is an obstacle")
        return None

    if grid[defect_cell[0]][defect_cell[1]] == 1:
        logger.error(f"Defect cell {defect_cell} is an obstacle")
        return None

    frontier = deque([start_cell])
    came_from = {start_cell: None}
    cost_so_far = {start_cell: 0}

    while frontier:
        current_cell = frontier.popleft()
        if current_cell == defect_cell:
            break

        for neighbor in get_neighbors(current_cell, GRID_SIZE):
            if grid[neighbor[0]][neighbor[1]] == 0:
                new_cost = cost_so_far[current_cell] + 1
                if neighbor not in cost_so_far or new_cost < cost_so_far[neighbor]:
                    cost_so_far[neighbor] = new_cost
                    came_from[neighbor] = current_cell
                    frontier.append(neighbor)

    if defect_cell not in came_from:
        logger.warning(f"No path found from {start_cell} to {defect_cell}")
        return None

    path = []
    current_cell = defect_cell
    while current_cell is not None:
        path.append(current_cell)
        current_cell = came_from[current_cell]

    path.reverse()
    return len(path)


def drive_led(led, on_time, blink_count, blink_interval):
    """Drive the LED with specified on/blink times."""
    try:
        if blink_count > 0:
            for _ in range(blink_count):
                if not running:
                    break
                led.on()
                time.sleep(on_time)
                led.off()
                time.sleep(blink_interval)
        else:
            led.on()
            time.sleep(on_time)
            led.off()
    except (GPIOZeroError, GPIODeviceError) as e:
        logger.error(f"LED control error: {e}")
    except Exception as e:
        logger.error(f"Unexpected LED error: {e}")


def main():
    """Main entry point."""
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize LED
    led = None
    try:
        led = LED(LED_PIN)
        logger.info(f"LED initialized on GPIO{LED_PIN}")
    except (GPIOZeroError, GPIODeviceError) as e:
        logger.error(f"Failed to initialize LED on GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Unexpected error initializing LED: {e}")
        sys.exit(1)

    try:
        validate_grid_dimensions(GRID_SIZE)
        grid = create_grid(GRID_SIZE)
        route_length = plan_route(grid, START_CELL, DEFECT_CELL)

        if route_length is not None:
            logger.info(f"Route planned successfully. Path length: {route_length}")
            drive_led(led, SUCCESS_LED_ON_TIME, 0, 0)
        else:
            logger.error("Failed to plan route. Check grid and obstacles.")
            drive_led(led, FAILURE_LED_ON_TIME, FAILURE_LED_BLINK_COUNT, FAILURE_LED_BLINK_INTERVAL)

    except ValueError as e:
        logger.error(f"Configuration error: {e}")
        drive_led(led, FAILURE_LED_ON_TIME, FAILURE_LED_BLINK_COUNT, FAILURE_LED_BLINK_INTERVAL)
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        drive_led(led, FAILURE_LED_ON_TIME, FAILURE_LED_BLINK_COUNT, FAILURE_LED_BLINK_INTERVAL)
    finally:
        if led is not None:
            try:
                led.close()
                logger.info("LED resource released")
            except Exception as e:
                logger.error(f"Error closing LED: {e}")


if __name__ == "__main__":
    main()

