import random
import json
import sys
from gpiozero import Device
from gpiozero.pins.mock import MockFactory

# Use MockFactory for simulation without real GPIO hardware
Device.pin_factory = MockFactory()

def generate_energy_level():
    """Simulates a voice recognition energy level (0-9)."""
    return random.randint(0, 9)

def transcribe_energy_level(energy_level):
    """Maps an energy level to a command keyword."""
    return {
        0: 'water',
        1: 'stop',
        2: 'status'
    }[energy_level % 3]

def perform_action(command_word):
    """Maps a command keyword to a farm action."""
    return {
        'water': 'open_valve',
        'stop': 'close_valve',
        'status': 'report'
    }[command_word]

def save_actions(actions_list):
    """Saves the list of chosen actions to a JSON file."""
    try:
        with open('voice_actions.json', 'w') as f:
            json.dump(actions_list, f, indent=2)
        print(f"Actions saved to voice_actions.json ({len(actions_list)} actions)")
    except IOError as e:
        print(f"Error saving actions: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    """Main function to simulate voice recognition and control a farm."""
    actions_list = []
    try:
        for frame_index in range(6):
            energy_level = generate_energy_level()
            command_word = transcribe_energy_level(energy_level)
            action = perform_action(command_word)
            actions_list.append(action)
            print(f"Frame {frame_index}: Energy={energy_level}, Word={command_word}, Action={action}")
    except Exception as e:
        print(f"Unexpected error during simulation: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        save_actions(actions_list)

if __name__ == "__main__":
    main()

