import atexit
import logging
import time

import board
import busio
import adafruit_pca9685

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SERVO_FREQUENCY = 60
MIN_PULSE_WIDTH = 150
MAX_PULSE_WIDTH = 600
MIN_ANGLE = -77
MAX_ANGLE = 77

PCA9685_ADDRESS = 0x40

class Fuchikoma:
    def __init__(self, i2c_bus=None):
        self.i2c_bus = i2c_bus if i2c_bus else busio.I2C(board.SCL, board.SDA)
        self.pwm = None
        self._channels = {}
        self._initialized = False

        try:
            self.pwm = adafruit_pca9685.PCA9685(self.i2c_bus, address=PCA9685_ADDRESS)
            self.pwm.frequency = SERVO_FREQUENCY
            logger.info(f"PCA9685 initialized at address 0x{PCA9685_ADDRESS:02X} on bus {self.i2c_bus.try_lock()}")
        except (ValueError, OSError) as e:
            logger.error(f"Failed to initialize PCA9685 at address 0x{PCA9685_ADDRESS:02X}: {e}")
            self.cleanup()
            raise

        self._channels = {
            'claw': 0,
            'lock': 1,
            'water_gun': 2,
        }
        self._initialized = True
        atexit.register(self.cleanup)

    def move_servo(self, servo_name, angle, delay=0.029):
        if not self._initialized:
            logger.error("PCA9685 not initialized. Cannot move servo.")
            return

        if servo_name not in self._channels:
            logger.error(f"Invalid servo name: {servo_name}")
            return

        channel = self._channels[servo_name]
        pulse_width = self._angle_to_pulse(angle)

        try:
            self.pwm.channels[channel].duty_cycle = pulse_width
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
        except (ValueError, OSError) as e:
            logger.error(f"Failed to move servo {servo_name} to angle {angle}: {e}")
            self.pwm.channels[channel].duty_cycle = 0

    def _angle_to_pulse(self, angle):
        if not (MIN_ANGLE <= angle <= MAX_ANGLE):
            logger.error(f"Angle {angle} out of range [{MIN_ANGLE}, {MAX_ANGLE}].")
            return 0
        return int((angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH)

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if self._initialized:
            try:
                for ch in self._channels.values():
                    self.pwm.channels[ch].duty_cycle = 0
                logger.info("All PCA9685 channels deinitialized.")
            except (ValueError, OSError) as e:
                logger.error(f"Error during cleanup: {e}")
            finally:
                self._initialized = False
        if self.i2c_bus:
            try:
                self.i2c_bus.deinit()
                logger.info("I2C bus deinitialized.")
            except Exception as e:
                logger.error(f"Error deinitializing I2C bus: {e}")

