#!/usr/bin/env python3
"""
Predictive maintenance for urban monitoring using an SW-420 digital vibration sensor.
Reads a digital output from GPIO17 (BCM) with internal pull-up.
Maintains a running average of amplitude readings.
"""

import random
import time
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Configuration
VIBRATION_SENSOR_PIN = 17          # BCM GPIO pin connected to SW-420 digital output
NUM_SAMPLES = 6
SAMPLE_INTERVAL = 0.3             # seconds between samples
MAINTENANCE_THRESHOLD = 7.5       # average amplitude threshold for maintenance

def read_vibration_amplitude(sensor):
    """
    Read the digital state of the vibration sensor.
    Returns:
        float: Amplitude value (6.0-9.0 for vibration, 3.0-5.0 for idle)
    """
    try:
        # sensor.value is 1 when pin reads LOW (vibration detected)
        if sensor.value == 1:
            return random.uniform(6.0, 9.0)
        else:
            return random.uniform(3.0, 5.0)
    except DeviceClosed:
        raise RuntimeError("Sensor device is closed")
    except GPIOZeroError as e:
        raise RuntimeError(f"GPIO error reading sensor: {e}")

def main():
    """Main function to run predictive maintenance loop."""
    sensor = None
    try:
        # Initialize digital input with internal pull-up
        sensor = DigitalInputDevice(
            VIBRATION_SENSOR_PIN,
            pull_up=True,
            bounce_time=None  # no hardware debounce
        )
        print(f"Vibration sensor initialized on GPIO{VIBRATION_SENSOR_PIN} (pull-up).")

        amplitude_readings = []
        for sample_index in range(NUM_SAMPLES):
            amplitude = read_vibration_amplitude(sensor)
            amplitude_readings.append(amplitude)
            print(f"Sample {sample_index + 1}: amplitude = {amplitude:.2f}")

            if sample_index < NUM_SAMPLES - 1:
                time.sleep(SAMPLE_INTERVAL)

        # Calculate running average
        average_amplitude = sum(amplitude_readings) / len(amplitude_readings)
        print(f"\nAverage amplitude: {average_amplitude:.2f}")

        # Check for maintenance recommendation
        if average_amplitude > MAINTENANCE_THRESHOLD:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

    except RuntimeError as e:
