import logging
import signal
import sys
import time

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
GPS_PORT = 9099
GPS_TIMEOUT = 2  # seconds

# Global state
tracking_state = False
gps_module = None
gps_socket = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def initialize_gps():
    """Initialize the GPS module. Returns a dict with lat and lon or None."""
    global gps_module
    try:
        # Use smbus2 for I2C communication
        from smbus2 import SMBus
        bus = SMBus(1)  # I2C bus 1 on Raspberry Pi
        # Check device presence with a quick read
        bus.read_byte(0x42)
        gps_module = {'type': 'I2C', 'bus': bus, 'address': 0x42}
        logging.info("GPS initialized via I2C at address 0x42")
        return {'lat': 0.0, 'lon': 0.0}
    except Exception as e:
        logging.warning(f"I2C GPS not found: {e}. Falling back to simulated coordinates.")

    try:
        import serial
        import serial.tools.list_ports
        # Find the first available UART port
        available_ports = [p.device for p in serial.tools.list_ports.comports()]
        if not available_ports:
            logging.warning("No UART ports found. Falling back to simulated coordinates.")
            return {'lat': 0.0, 'lon': 0.0}

        # Use the first available port
        port = available_ports[0]
        gps_module = {'type': 'UART', 'port': port, 'baudrate': 9600}
        logging.info(f"GPS initialized via UART on {port}")
        return {'lat': 0.0, 'lon': 0.0}
    except Exception as e:
        logging.warning(f"UART GPS not available: {e}. Falling back to simulated coordinates.")
        return {'lat': 0.0, 'lon': 0.0}


def read_gps_position():
    """Read GPS coordinates from the module. Returns a dict with lat and lon or None."""
    global gps_module
    if gps_module is None:
        return None

    if gps_module['type'] == 'I2C':
        try:
            # Read 6 bytes from the GPS module
            data = gps_module['bus'].read_i2c_block_data(gps_module['address'], 0x00, 6)
            # Parse the data
            # For simplicity, we assume the data is in a fixed format
            # In a real implementation, you would parse the NMEA sentence
            lat = 0.0
            lon = 0.0
            return {'lat': lat, 'lon': lon}
        except Exception as e:
            logging.error(f"I2C read error: {e}")
            return None
    elif gps_module['type'] == 'UART':
        try:
            # Read a line from the UART
            line = gps_module['port'].readline().decode('utf-8', errors='ignore').strip()
            if not line:
                return None
            # Parse the line
            # For simplicity, we assume the data is in a fixed format
            # In a real implementation, you would parse the NMEA sentence
            lat = 0.0
            lon = 0.0
            return {'lat': lat, 'lon': lon}
        except Exception as e:
            logging.error(f"UART read error: {e}")
            return None
    else:
        logging.warning("Unknown GPS module type. Returning simulated coordinates.")
        return {'lat': 0.0, 'lon': 0.0}


def handle_command(command):
    """Handle a remote control command and update the tracking state."""
    global tracking_state
    if command == 'start':
        tracking_state = True
        logging.info("Tracking started")
    elif command == 'stop':
        tracking_state = False
        logging.info("Tracking stopped")
    elif command == 'report':
        gps_data = read_gps_position()
        if gps_data:
            logging.info(f"GPS Report: Latitude={gps_data['lat']}, Longitude={gps_data['lon']}")
            return json.dumps({'lat': gps_data['lat'], 'lon': gps_data['lon']})
        else:
            logging.warning("Failed to retrieve GPS data for report")
            return None
    else:
        logging.warning(f"Invalid command: {command}")
        return None


def main():
    """Main function to accept remote control commands and handle them."""
    global gps_socket, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPS
    gps_data = initialize_gps()

    # Create a TCP socket
    try:
        gps_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        gps_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        gps_socket.bind(('127.0.0.1', GPS_PORT))
        gps_socket.listen(5)
        gps_socket.settimeout(GPS_TIMEOUT)
        logging.info(f"Listening on port {GPS_PORT} for GPS commands...")
    except socket.error as e:
        logging.error(f"Failed to create socket: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                # Accept a connection
                connection, address = gps_socket.accept()
                logging.info(f"Connection from {address}")

                # Receive command
                try:
                    command = connection.recv(1024).decode('utf-8', errors='ignore').strip()
                except socket.error as e:
                    logging.error(f"Socket error receiving command: {e}")
                    connection.close()
                    continue

                # Handle command
                response = handle_command(command)

                # Send response
                if response:
                    try:
                        connection.sendall(response.encode('utf-8'))
                    except socket.error as e:
                        logging.error(f"Socket error sending response: {e}")
                else:
                    logging.warning("No response to command")

                # Close the connection
                connection.close()
                logging.info(f"Connection from {address} closed")

            except socket.timeout:
                # No connection received within timeout
                continue
            except socket.error as e:
                logging.error(f"Socket error: {e}")
                break
    finally:
        # Cleanup resources
        if gps_socket:
            gps_socket.close()
            logging.info("GPS socket closed")
        if gps_module and gps_module['type'] == 'I2C':
            try:
                gps_module['bus'].close()
                logging.info("I2C bus closed")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
        logging.info("Program terminated")


if __name__ == "__main__":
    main()

