"""
Automated Chicken Coop Door Controller

Controls a relay on GPIO 17 (BCM) to simulate an automated chicken coop door.
Uses RPi.GPIO for GPIO control, time for delays, and datetime for time-of-day comparisons.
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
RELAY_PIN = 17
SUNRISE_TIME = datetime.time(7, 0, 0)
SUNSET_TIME = datetime.time(19, 0, 0)
CHECK_INTERVAL = 60  # seconds

def setup_gpio():
    """Initialize GPIO pin for relay control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)  # Relay de-energized, door closed
        print("GPIO initialized successfully.")
    except RuntimeError as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}")
        sys.exit(1)

def get_current_time():
    """Return current time as datetime.time object."""
    return datetime.datetime.now().time()

def is_sunrise_or_sunset(current_time):
    """Check if current time is between sunrise and sunset (inclusive)."""
    return SUNRISE_TIME <= current_time <= SUNSET_TIME

def control_door(is_open):
    """Set relay state based on door state."""
    try:
        if is_open:
            GPIO.output(RELAY_PIN, GPIO.LOW)  # Relay energized, door open
            print("Door opened")
        else:
            GPIO.output(RELAY_PIN, GPIO.HIGH)  # Relay de-energized, door closed
            print("Door closed")
    except Exception as e:
        print(f"Error controlling door: {e}")

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
        print("GPIO cleaned up.")
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

if __name__ == "__main__":
    setup_gpio()
    try:
        while True:
            current_time = get_current_time()
            is_sunrise = is_sunrise_or_sunset(current_time)
            control_door(is_sunrise)
            time.sleep(CHECK_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup_gpio()
        print("Exiting program.")

