#!/usr/bin/env python3
"""
Smart Garden Pump Controller
Monitors an HC-SR501 PIR motion sensor on GPIO 4 (BCM).
Logs feeding events with timestamps, enforces cooldown, and handles errors.
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
PIR_PIN = 4
FEEDING_START_HOUR = 7
FEEDING_END_HOUR = 23
DEBOUNCE_SECONDS = 60
POLL_INTERVAL = 1  # seconds

def is_feeding_time(now):
    """Return True if current time is between feeding hours (24-hour format)."""
    hour = now.hour
    return FEEDING_START_HOUR <= hour < FEEDING_END_HOUR

def setup_gpio():
    """Initialize GPIO mode and PIR pin with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        print("GPIO setup complete.")
    except Exception as e:
        print(f"Fatal: GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
        print("GPIO cleanup complete.")
    except Exception as e:
        print(f"Warning: GPIO cleanup error: {e}")

def main():
    setup_gpio()
    last_feeding_time = None
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading PIR sensor: {e}")
                time.sleep(POLL_INTERVAL)
                continue

            now = datetime.datetime.now()
            timestamp = now.strftime("%Y-%m-%d %H:%M:%S")

            if motion_detected:
                if is_feeding_time(now) and (last_feeding_time is None or (now - last_feeding_time).total_seconds() >= DEBOUNCE_SECONDS):
                    print(f"Motion detected at {timestamp}")
                    print("Feeding initiated at", timestamp)
                    last_feeding_time = now
                else:
                    print(f"Motion detected at {timestamp}, but not feeding time or cooldown.")
            else:
                if last_feeding_time is not None and (now - last_feeding_time).total_seconds() >= DEBOUNCE_SECONDS:
                    print(f"No motion for {DEBOUNCE_SECONDS}s, feeding complete.")
                    last_feeding_time = None

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

