import RPi.GPIO as GPIO
import time
import sys

# GPIO pin definitions (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_gpio():
    """Initialize GPIO pins for the healthcare monitoring cart."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def read_sensor(sensor_pin):
    """Read the state of a TCRT5000 reflectance sensor.
    Returns True if the sensor detects a dark line (LOW), False otherwise."""
    try:
        return GPIO.input(sensor_pin) == GPIO.LOW
    except Exception as e:
        print(f"Error reading sensor on pin {sensor_pin}: {e}", file=sys.stderr)
        return False

def control_motors(left_on, right_on):
    """Set the left and right motor outputs."""
    try:
        GPIO.output(LEFT_MOTOR_PIN, left_on)
        GPIO.output(RIGHT_MOTOR_PIN, right_on)
    except Exception as e:
        print(f"Error controlling motors: {e}", file=sys.stderr)

def cleanup_gpio():
    """Safely clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}", file=sys.stderr)

def main():
    setup_gpio()
    try:
        for iteration in range(20):
            left_detected = read_sensor(LEFT_SENSOR_PIN)
            right_detected = read_sensor(RIGHT_SENSOR_PIN)

            if left_detected and not right_detected:
                control_motors(True, False)  # Turn left
            elif right_detected and not left_detected:
                control_motors(False, True)  # Turn right
            elif left_detected and right_detected:
                control_motors(True, True)   # Go straight
            else:
                control_motors(False, False)  # Stop

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nMonitoring cart stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

