#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller
Hardware: Raspberry Pi, Relay Module (active-high)
GPIO Pin: GPIO17 (BCM)
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
RELAY_PIN = 17
SUNRISE_HOUR = 7
SUNSET_HOUR = 19
CHECK_INTERVAL = 60  # seconds

def setup_gpio():
    """Initialize GPIO mode and set relay pin as output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
        print("GPIO setup complete.")
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def control_door(is_opening):
    """Energize or de-energize relay to control door."""
    try:
        if is_opening:
            GPIO.output(RELAY_PIN, GPIO.HIGH)
            print("Door opened")
        else:
            GPIO.output(RELAY_PIN, GPIO.LOW)
            print("Door closed")
    except Exception as e:
        print(f"Error controlling door: {e}", file=sys.stderr)

def main():
    setup_gpio()
    print("Chicken coop door controller started. Press Ctrl+C to exit.")

    try:
        while True:
            now = datetime.datetime.now().time()
            if now.hour >= SUNRISE_HOUR and now.hour < SUNSET_HOUR:
                control_door(False)  # Open door
            else:
                control_door(True)   # Close door
            time.sleep(CHECK_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

