import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_co2_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading serial data: {e}", file=sys.stderr)
        return None

def log_co2_data(co2_value, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2 Concentration: {co2_value} ppm\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            co2_data = read_co2_data(serial_connection)
            if co2_data:
                try:
                    co2_value = int(co2_data)
                    print(f"CO2 Concentration: {co2_value} ppm")
                    log_co2_data(co2_value, LOG_FILE)
                except ValueError:
                    print(f"Invalid data received (not an integer): {co2_data}", file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

