import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial_connection = None
        self._running = True

        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baud_rate,
                timeout=self.timeout
            )
            print(f"Serial connection established on {self.port} at {self.baud_rate} baud.")
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}")
            self.serial_connection = None
            raise

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.serial_connection or not self.serial_connection.is_open:
            print("Serial connection is not open.")
            return None

        try:
            self.serial_connection.reset_input_buffer()
            self.serial_connection.write(command.encode('utf-8'))
            self.serial_connection.flush()

            start_time = time.time()
            response = b''

            while time.time() - start_time < timeout:
                if self.serial_connection.in_waiting > 0:
                    chunk = self.serial_connection.read(self.serial_connection.in_waiting)
                    if chunk:
                        response += chunk
                        if wait_for in response:
                            return response
                else:
                    time.sleep(0.01)

            print(f"Timeout waiting for response to command: {command}")
            return None

        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT', timeout=1.0)
        if response and b'OK' in response:
            print("ESP8266 module is responding.")
            return True
        print("ESP8266 module is not responding.")
        return False

    def restart(self):
        response = self._send_command('AT+RST', timeout=1.0)
        if response and b'OK' in response:
            print("ESP8266 module restarted.")
            time.sleep(2)  # Wait for module to reboot
            return True
        print("Failed to restart ESP8266 module.")
        return False

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, timeout=10.0)
        if response and b'OK' in response:
            print("Connected to WiFi network.")
            return True
        print("Failed to connect to WiFi network.")
        return False

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP', timeout=1.0)
        if response and b'OK' in response:
            print("Disconnected from WiFi network.")
            return True
        print("Failed to disconnect from WiFi network.")
        return False

    def get_ip(self):
        response = self._send_command('AT+CIFSR', timeout=1.0)
        if response:
            try:
                lines = response.decode('utf-8').split('\r\n')
                for line in lines:
                    if 'STAIP' in line:
                        ip_address = line.split('=')[1].strip()
                        print(f"IP address: {ip_address}")
                        return ip_address
            except Exception as e:
                print(f"Error parsing IP address: {e}")
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self.serial_connection or not self.serial_connection.is_open:
            print("Serial connection is not open.")
            return None

        try:
            self.serial_connection.reset_input_buffer()

            request = f"{method} {url} HTTP/1.1\r\n"
            request += f"Host: {host}\r\n"
            request += f"Connection: close\r\n"
            if headers:
                for key, value in headers.items():
                    request += f"{key}: {value}\r\n"
            if data:
                request += f"Content-Length: {len(data)}\r\n"
            request += "\r\n"
            request += data if data else ""

            self.serial_connection.write(request.encode('utf-8'))
            self.serial_connection.flush()

            start_time = time.time()
            response = b''

            while time.time() - start_time < 5.0:
                if self.serial_connection.in_waiting > 0:
                    chunk = self.serial_connection.read(self.serial_connection.in_waiting)
                    if chunk:
                        response += chunk
                        if b'CLOSED' in response:
                            print("HTTP connection closed.")
                            return response
                else:
                    time.sleep(0.01)

            print("Timeout waiting for HTTP response.")
            return None

        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def receive_http_response(self, timeout=5.0):
        if not self.serial_connection or not self.serial_connection.is_open:
            print("Serial connection is not open.")
            return None

        try:
            start_time = time.time()
            response = b''

