import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1.0
SLEEP_INTERVAL = 1.0

running = True
serial_connection = None
alarm = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_connection, alarm
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
    if alarm is not None:
        try:
            alarm.close()
            print("GPIO alarm pin released.")
        except Exception as e:
            print(f"Error releasing GPIO: {e}")

def main():
    global serial_connection, alarm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        alarm = OutputDevice(ALARM_PIN, initial_value=False)
        print(f"GPIO alarm pin {ALARM_PIN} initialized LOW.")
    except Exception as e:
        print(f"Failed to initialize GPIO pin {ALARM_PIN}: {e}")
        sys.exit(1)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        cleanup()
        sys.exit(1)

    alarm_state = False

    try:
        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    radiation_level = float(line)
                except ValueError:
                    print(f"Invalid data received (not a float): '{line}'")
                    continue

                print(f"Radiation Level: {radiation_level:.2f} µSv/h")

                if radiation_level > RADIATION_THRESHOLD:
                    if not alarm_state:
                        alarm.on()
                        alarm_state = True
                        print("Alarm activated!")
                else:
                    if alarm_state:
                        alarm.off()
                        alarm_state = False
                        print("Alarm deactivated!")

            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

            time.sleep(SLEEP_INTERVAL)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

