import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} initialized at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port {port}: {e}", file=sys.stderr)
        return None

def read_co2_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return int(line)
    except ValueError:
        print(f"Warning: Invalid data received (not an integer): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None

def log_co2_data(co2_value, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2 Concentration: {co2_value} ppm\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
        print(log_entry.strip())
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            co2_level = read_co2_data(serial_connection)
            if co2_level is not None:
                log_co2_data(co2_level, LOG_FILE)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

