import serial
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial connection error on {self.port}: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.error("Serial connection is not open.")
            return None

        try:
            raw_data = self.serial_connection.readline()
            if not raw_data:
                return None
            data = raw_data.decode('utf-8', errors='ignore').strip()
            return data
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            self.close()
            return None
        except OSError as e:
            logging.error(f"OS read error: {e}")
            self.close()
            return None

    def parse_gga(self, sentence):
        if not sentence:
            return None

        if sentence.startswith('$GPGGA') or sentence.startswith('$GNGGA'):
            try:
                fields = sentence.split(',')
                utc_time = fields[1]
                latitude = fields[2]
                latitude_dir = fields[3]
                longitude = fields[4]
                longitude_dir = fields[5]
                fix_quality = fields[6]
                num_satellites = fields[7]

                if not utc_time or not latitude or not latitude_dir or not longitude or not longitude_dir:
                    return None

                latitude_decimal = self._convert_to_decimal(latitude, latitude_dir)
                longitude_decimal = self._convert_to_decimal(longitude, longitude_dir)

                return {
                    'utc_time': utc_time,
                    'latitude': latitude_decimal,
                    'longitude': longitude_decimal,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
            except (IndexError, ValueError) as e:
                logging.error(f"GGA parse error: {e} - sentence: {sentence}")
                return None
        return None

    def _convert_to_decimal(self, coordinate, direction):
        try:
            degrees = float(coordinate[:2])
            minutes = float(coordinate[2:])
            decimal = degrees + (minutes / 60.0)
            if direction == 'S' or direction == 'W':
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.error(f"Invalid coordinate format: {e}")
            return None

    def close(self):
