import serial

app = Flask(__name__)

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

shutdown_event = threading.Event()


class SerialCommunicator:
    """Thread-safe serial communicator with error handling and cleanup."""

    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.lock = threading.Lock()
        self.serial_conn = None
        self._open()

    def _open(self):
        """Open the serial port; raise on failure."""
        with self.lock:
            if self.serial_conn is not None and self.serial_conn.is_open:
                return
            try:
                self.serial_conn = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                print(f"Serial port {self.port} opened at {self.baudrate} baud.")
            except serial.SerialException as exc:
                raise RuntimeError(f"Failed to open serial port {self.port}: {exc}") from exc

    def send(self, cmd):
        """Send a command line and return the decoded response line."""
        if self.serial_conn is None or not self.serial_conn.is_open:
            raise RuntimeError("Serial port is not open")
        with self.lock:
            try:
                payload = (cmd + "\n").encode("ascii")
                written = self.serial_conn.write(payload)
                if written != len(payload):
                    raise serial.SerialException(
                        f"Incomplete write: {written}/{len(payload)} bytes"
                    )
                self.serial_conn.flush()
                raw = self.serial_conn.readline()
                if not raw:
                    raise serial.SerialException("No response (timeout)")
                return raw.decode("ascii", errors="replace").strip()
            except serial.SerialException as exc:
                raise RuntimeError(f"Serial communication error: {exc}") from exc

    def receive_line(self):
        """Read one line from the serial port; return None on timeout/error."""
        if self.serial_conn is None or not self.serial_conn.is_open:
            return None
        with self.lock:
            try:
                raw = self.serial_conn.readline()
                if not raw:
                    return None
                return raw.decode("ascii", errors="replace").strip()
            except serial.SerialException as exc:
                return None

    def close(self):
        """Close the serial port if open."""
        with self.lock:
            if self.serial_conn is not None and self.serial_conn.is_open:
                try:
                    self.serial_conn.close()
                    print("Serial port closed.")
                except serial.SerialException as exc:
                    print(f"Warning: error closing serial port: {exc}")
                finally:
