    def get_all(self):
        with self.lock:
            return list(self.data)

    def get_by_id(self, item_id):
        with self.lock:
            return next((d for d in self.data if d["id"] == item_id), None)

    def create(self, name, done):
        if not isinstance(name, str) or not name.strip():
            return None
        if not isinstance(done, bool):
            return None
        with self.lock:
            item = {"id": self._next_id, "name": name, "done": done}
            self.data.append(item)
            self._next_id += 1
            return item


