import json
import time
import signal
import sys
from flask import Flask, request, jsonify, Response
import serial

app = Flask(__name__)

data_store = []
serial_port = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def init_serial():
    global serial_port
    try:
        serial_port = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        time.sleep(0.1)
        return True
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return False

def send_scpi(command):
    global serial_port
    if serial_port is None or not serial_port.is_open:
        return None
    try:
        serial_port.reset_input_buffer()
        serial_port.write((command + '\n').encode('ascii'))
        serial_port.flush()
        response = b''
        while serial_port.in_waiting > 0:
            chunk = serial_port.read(serial_port.in_waiting)
            if chunk:
                response += chunk
        return response.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

@app.route('/version', methods=['GET'])
def version():
    if not init_serial():
        return Response("Serial port unavailable", status=503, mimetype='text/html')
    try:
        response = send_scpi('*IDN?\n')
        if response:
            return Response(response.replace('\n', '<br>'), mimetype='text/html')
        else:
            return Response("No response from instrument", status=503, mimetype='text/html')
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()

@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(data_store)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    item = next((i for i in data_store if i['id'] == item_id), None)
    if item:
        return jsonify(item)
    return jsonify({'error': 'Item not found'}), 404

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post(item_id, name):
    item = next((i for i in data_store if i['id'] == item_id), None)
    if item:
        item['name'] = name
        return jsonify(data_store)
    return jsonify({'error': 'Item not found'}), 404

@app.route('/postjson', methods=['POST'])
def post_json():
    if request.method == 'POST':
        if request.is_json:
            data = request.get_json()
            try:
                item_id = int(data.get('id', 0))
                name = data.get('name', '')
                done = bool(data.get('done', False))
                new_item = {'id': item_id, 'name': name, 'done': done}
                data_store.append(new_item)
                return jsonify(data_store)
            except (ValueError, TypeError):
                return jsonify({'error': 'Invalid JSON input'}), 400
        else:
            data = request.form.to_dict(flat=False)
            try:
                item_id = int(data.get('id', 0))
                name = data.get('name', '')
                done = bool(data.get('done', False))
                new_item = {'id': item_id, 'name': name, 'done': done}
                data_store.append(new_item)
                return jsonify(data_store)
            except (ValueError, TypeError):
                return jsonify({'error': 'Invalid form input'}), 400
    return jsonify({'error': 'Method not allowed'}), 405

